import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  totalPrice: 0,
  count: 0,
};

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addProduct(state, action) {
      state.items = [
       ...state.items,
        {
          id: action.payload.id,
          title: action.payload.title,
          quantity: 1,
          price: action.payload.price,
        },
      ];

      state.totalPrice += action.payload.price;
      state.count++;
    },
    removeProduct(state, action) {
      state.items = state.items.filter((product) => product.id!== action.payload.id);
      state.totalPrice -= state.items
       .filter((product) => product.id === action.payload.id)
       .map((product) => product.price);
      state.count--;
    },
    increaseProduct(state, action) {
      const productIndex = state.items.findIndex((product) => product.id === action.payload.id);
      state.items[productIndex].quantity++;
      state.totalPrice += action.payload.price;
      state.count++;
    },
    decreaseProduct(state, action) {
      const productIndex = state.items.findIndex((product) => product.id === action.payload.id);
      if (state.items[productIndex].quantity > 1) {
        state.totalPrice -= action.payload.price;
        state.count--;
        state.items[productIndex].quantity--;
      }
    },
  },
});

export const { addProduct, removeProduct, increaseProduct, decreaseProduct } = cartSlice.actions;
```

