function CartComponent({ checkoutUrl }) {
  const dispatch = useDispatch();
  const cart = useSelector(state => state.cart);
  const { items, total } = cart;

  const handleRemoveItem = item => dispatch(removeItem(item.id));
  const handleDecrementQuantity = item => {
    dispatch(updateItem({
      id: item.id,
      quantity: item.quantity - 1,
    }));
  };
  const handleIncrementQuantity = item => {
    dispatch(updateItem({
      id: item.id,
      quantity: item.quantity + 1,
    }));
  };

  return (
    <div>
      <h2>Shopping Cart</h2>
      <ul>
        {items.map(item => (
          <li key={item.id}>
            <img src={item.thumbnail} alt={item.name} />
            {item.name} x {item.quantity}
            <button onClick={() => handleDecrementQuantity(item)}>−</button>
            <button onClick={() => handleIncrementQuantity(item)}>+</button>
            <button onClick={() => handleRemoveItem(item)}>Remove</button>
            <span>
              ${item.price * item.quantity}
            </span>
          </li>
        ))}
      </ul>
      <p>Total: ${total}</p>
      <a href={checkoutUrl}>Checkout</a>
    </div>
  );
}
```

